import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"CineMobile: On-Device Image-to-Video Diffusion for Cinematic Camera Motion Generation","description":"","frontmatter":{"title":"CineMobile: On-Device Image-to-Video Diffusion for Cinematic Camera Motion Generation","arxiv":"2607.03803","date":"2026-07-04","authors":"Xuyao Huang, Zelai Deng, Xu Wang, Xizhong Xiao, Zhijie Deng","categories":"cs.CV, cs.AI","topics":"端侧部署, 结构化剪枝, 步数蒸馏","outline":[2,2]},"headers":[],"relativePath":"papers/2607.03803.md","filePath":"papers/2607.03803.md","lastUpdated":null}'),e={name:"papers/2607.03803.md"};function l(i,s,r,m,o,c){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="cinemobile-on-device-image-to-video-diffusion-for-cinematic-camera-motion-generation" tabindex="-1">CineMobile: On-Device Image-to-Video Diffusion for Cinematic Camera Motion Generation <a class="header-anchor" href="#cinemobile-on-device-image-to-video-diffusion-for-cinematic-camera-motion-generation" aria-label="Permalink to &quot;CineMobile: On-Device Image-to-Video Diffusion for Cinematic Camera Motion Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.03803" target="_blank" rel="noreferrer">2607.03803</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-04</td></tr><tr><td><strong>作者</strong></td><td>Xuyao Huang, Zelai Deng, Xu Wang, Xizhong Xiao, Zhijie Deng</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把任务从&quot;通用 I2V&quot;收窄到子弹时间/滑动变焦/慢动作三种运动模式明确的电影镜头效果，再用&quot;只剪深度不剪宽度的结构化剪枝 + AdvDMD 四步对抗蒸馏 + FFN 4bit 其余 8bit 的混合量化&quot;三级压缩，把模型压到 1 GB 以内跑在联发科天玑 8400 上。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/acceleration-distillation">加速与蒸馏</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>手机是视觉内容创作的主战场，而 I2V 的诉求高度集中在几种电影感镜头效果上：子弹时间、滑动变焦（希区柯克效应）、慢动作。技术侧的现实是：Wan2.1-I2V-14B 在 H200 上生成 49 帧 832×480 视频（40 步）要 240 秒，端侧部署无从谈起。</p><p>论文的一个关键判断是关于<strong>任务边界</strong>的：I2V 模型在激进加速下难以忠实保留 prompt 语义，因此不要去做开放语义的通用生成，而是聚焦&quot;运动目标结构化、可控&quot;的相机运动效果。这个收窄不是技术妥协的托词，而是压缩可行性的前提——三种效果各自有明确的运动先验，可以用 effect-specific LoRA 挂在共享骨干上，主干只需要保住人像细节与时序一致性。</p><p>重要性在于：现有的端侧视频生成加速工作绝大多数针对 U-Net 架构，而 DiT 已经是事实标准，这条迁移路径几乎空白。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>端侧视频生成</strong>。Mobile Video Diffusion 用降分辨率、时序多尺度、剪枝与对抗微调压缩 I2V；On-device Sora 用降步数、时序 token merging、动态加载；SnapGen-V 用高效空间骨干 + 面向移动端的时序设计 + 对抗低步训练做到 5 秒交互式生成；Taming Diffusion Transformer 把这条线扩到 DiT，用高压缩 VAE、敏感度感知剪枝与面向移动端的步数蒸馏。</p><p><strong>步数蒸馏</strong>。从 DDIM、Progressive Distillation 到 LCM、ADD、DMD/DMD2；视频侧有 VideoLCM、AnimateLCM、T2V-Turbo 系列。</p><p><strong>剪枝</strong>。本文直接复用 PPCL（Pluggable Pruning with Contiguous Layer Distillation），它原本是为文生图 DiT 设计的：先检测冗余的连续层区间，再做深度与宽度剪枝并蒸馏。</p><p>不足的精确表述：这些工作要么面向 U-Net、要么面向 T2I，缺的是&quot;DiT 架构 + I2V 任务 + 真实手机 SoC&quot;这三者同时成立的完整流水线。而把 PPCL 直接搬到视频 DiT 会遇到一个具体障碍——<strong>宽度剪枝会改变内部特征维度，扰乱预训练的时序表征</strong>，表现为身份漂移与细节退化（论文附录 C 的定性对比）。这一条是本文相对 PPCL 的实质性调整。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>给定&quot;要在天玑 8400 上跑 DiT I2V&quot;这个目标，成本来自三个乘数：参数量、步数、每参数的字节数。三者需要分别攻击，且顺序不能乱。</p><p>先看参数量。1.5B 的 Wan2.1-v1.1-Fun 已经是可选的最小 I2V 底座，再压只能剪枝。剪深度还是剪宽度？宽度剪枝改的是 hidden dim，会把整个骨干推离预训练特征空间；深度剪枝只是删掉若干层变换，剩余层仍在原特征空间里工作。对&quot;必须保住人像细节与相机轨迹平滑&quot;的任务，后者风险小得多。这一步是任务性质直接推出的设计选择。</p><p>再看步数。20 步降到 4 步。但直接对刚剪完的模型做步数蒸馏会训练不稳甚至崩溃——剪枝已经破坏了模型，再叠一个更难的目标就没有可用的初始化。所以必须插一个 SFT warm-up：先用原始稠密模型生成的视频恢复基础生成能力，再用带效果 LoRA 的教师生成的效果视频把分布对齐到目标运动模式。</p><p>最后看字节数。FFN 占 DiT 参数的大头，把它压到 4 bit 收益最大；attention/text-embedding/time-embedding 投影对精度更敏感，保 FP8；激活保 16 bit 保数值稳定性。</p><p>整条链条的逻辑是&quot;每一级压缩都为下一级提供可训练的初始化&quot;，这也解释了为什么论文的消融只能是逐级累加式的。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>端侧跑 DiT 视频生成不是靠某一个技巧，而是靠三个乘数各砍一刀：层数、步数、位宽。关键的两处判断是：视频 DiT 的时序表征绑在 hidden dim 上，所以只能剪层不能剪宽；而刚剪完的模型太脆，必须先用教师视频做 SFT 把它扶起来，才有资格进对抗蒸馏。把任务从开放语义收窄到三种运动模式明确的镜头效果，是让这三刀都砍得下去的前提。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以子弹时间为例，从一张人像照片到手机上的 49 帧 480p 视频：</p><p><strong>离线阶段一：冗余区间检测</strong>。对教师 DiT 的每个 block 训一个残差线性探针，判断它的变换能否被轻量替代品近似；结合 CKA 相似度对候选区间按&quot;表征相似度 + 可删深度&quot;排序。为适配视频，候选区间在 latent 视频序列上评估，用了 5000+ 条标定样本。</p><p><strong>离线阶段二：区间蒸馏</strong>。对每个选中区间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathnormal">u</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mclose">]</span></span></span></span>，用一个可训练的代理 block <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">u</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 整体替换，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">u</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与原 block 同结构同宽度，用区间中点的 block 初始化。冻结底座，只更新代理 block，训练目标是复现教师在区间出口的 hidden state（归一化隐状态对齐）。训练数据是冻结底座自己合成的人像与运动视频。训完保留 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">u</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、删掉 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8917em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">u</span><span class="mbin mtight">+</span><span class="mord mtight">1..</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>。最终从 Wan2.1-v1.1-Fun-1.5B 得到 27 层、1.2B 的学生，再训 8k 步恢复能力。</p><p><strong>离线阶段三：SFT warm-up</strong>（5k 步，lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>，LoRA rank 128，遵循 DiffSynth-Studio 实现）。先在原稠密模型生成的视频上用 flow matching 目标恢复基础生成能力，再在教师（Wan2.1-I2V-14B + 效果 LoRA）生成的效果视频上对齐目标运动分布。</p><p><strong>离线阶段四：对抗蒸馏</strong>（AdvDMD 扩展到视频 DiT）。学生从 warm-up checkpoint 初始化，用 LoRA 更新，走 4 步去噪轨迹。冻结的 real model <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（教师 + 效果 LoRA）与在线 fake model <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span></span></span></span>（共享学生骨干、随机初始化 LoRA）分别估计真实与伪造 score 方向，其差构成 DMD 损失；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span></span></span></span> 上挂一个轻量判别器头，从多层时空 DiT 特征映射出真实性 logits，提供对抗损失，<strong>同一组判别器分数还被当作 GRPO 的 reward</strong> 去精修 4 步轨迹。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight" style="margin-right:0.0139em;">adv</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathrm mtight">D</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.005</span></span></span></span>，生成器每 5 步更新一次，其余步更新 fake model 与判别器。8 张 H200，10K+ 训练样本。</p><p><strong>离线阶段五：混合精度 PTQ</strong>。FFN 的两个线性层用 4 bit 权重 + 16 bit 激活，其余量化线性层用 FP8 权重，模型体积压到 1 GB 以内。</p><p><strong>端侧推理</strong>：Infinix NOTE 60 Ultra（天玑 8400 Ultimate，Mali-G720 MP7 约 2.33 TFLOPS FP32），4 步去噪，每步 20.02 s；附录 Figure 9 给出内存实测：待机 3994 MB，加载后 5121 MB（+1127），推理峰值 5857 MB（相对待机 +1863 MB）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。全文没有编号公式，方法描述停留在组件与超参层面（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight" style="margin-right:0.0139em;">adv</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathrm mtight">D</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.005</span></span></span></span>、LoRA rank 128、生成器每 5 步更新一次），DMD 损失、对抗损失与 GRPO 目标均只以文字叙述给出、引用原论文，未写出具体形式。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>评测协议</strong>。200 张人像测试图，每张生成 5 条视频，按 VBench 官方协议评。作者<strong>主动裁掉了两个维度</strong>并给出理由：Dynamic Degree 衡量运动幅度，而目标效果不由幅度定义，更高的运动度不代表效果更好；VBench 的相机控制分则因为对比对象（Wan2.1 系）本身没有针对这三种效果适配，读起来不公平。效果本身的质量改由定性结果与人评评估。</p><p><strong>主结果（Table 1）</strong>。以 Ours（4 步、1.2B）对 Wan2.1-I2V-14B 教师（20 步、14B）：子弹时间 88.35 vs 89.27（差 0.92），滑动变焦 89.30 vs 89.96（差 0.66），慢动作 88.05 vs 88.51（差 0.46）。参数量 10%、步数 20%。</p><p>有几处需要看清。<strong>未剪枝的 1.5B 底座 Wan2.1-v1.1-Fun（20 步）总分 88.81，高于最终模型在子弹时间上的 88.35 与慢动作上的 88.05</strong>；剪枝后的 Ours-Prune（20 步）是 88.34，与最终 4 步模型的 88.35 几乎相同。也就是说在 VBench 这套指标下，<strong>主要的分数损失发生在剪枝这一步，而后续的 SFT + 蒸馏 + 量化几乎把损失又补了回来</strong>。另外滑动变焦上 4 步的 Ours（89.30）反而高于自己 20 步的 Ours-SFT（89.14），论文未讨论。</p><p><strong>效率（Figure 2）</strong>。教师 97.06 s 去噪、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3.35</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">16</span></span></span></span></span></span></span></span></span></span></span></span> DiT-FLOPs。剪枝把底座从 16.42 s 降到 12.28 s（收益有限）；步数蒸馏是主力，降到 2.45 s、FLOPs 降到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4.66</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">14</span></span></span></span></span></span></span></span></span></span></span></span>；混合量化主要贡献显存而非速度。合计 40.11× 去噪加速、71.89× FLOPs 下降。端侧每步 20.02 s，4 步意味着 DiT 部分约 80 s，摘要中的&quot;0.6 s/步（H200）与 20 s/步（天玑）&quot;是<strong>每步</strong>口径。</p><p><strong>GRPO 消融（Table 2，子弹时间）</strong>。基座模型 88.25→88.77（+0.52），CineMobile 87.88→88.35（+0.47）。作者说增益主要来自感知类指标。逐项看确实如此但不是单向的：CineMobile 侧 Imaging Quality 68.90→70.71、I2V Subject 97.36→98.15、Background Consis 93.21→94.06 上升，而 <strong>Motion Smoothness 99.00→98.76、Subject Consis 93.54→93.46、I2V Background 98.77→98.58 下降</strong>；基座侧 Background Consis 也从 94.91 降到 94.36。</p><p><strong>与帧插值对比（Figure 7）</strong>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20</span><span class="mord">×</span></span></span></span> 慢动作、只给首尾帧：PSNR 30.57→35.68 dB、SSIM 0.713→0.858，优于 FILM，且 FILM 会出现物体互穿与运动不一致。</p><p><strong>人评（Figure 6）</strong>。50 条子弹时间视频、10 名参与者、匿名随机化，对比 Kling、Hailuo、Vidu。结论是整体竞争力相当、<strong>相机控制维度最强</strong>。图中未给出数值。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：端侧 DiT 视频生成要同时砍层数、步数和位宽，三者顺序不能乱，因为每一级压缩都要为下一级提供可训练的初始化。视频 DiT 的时序表征绑在 hidden dim 上，宽度剪枝会造成身份漂移，因此只做深度剪枝（1.5B→1.2B，27 层）。刚剪完的模型直接上步数蒸馏会崩，必须先用稠密模型与教师效果视频做两段 SFT warm-up。四步生成靠 AdvDMD：DMD 分布匹配 + 判别器对抗 + 把判别器分数当 GRPO reward。最终 40.11× 去噪加速、模型 &lt;1 GB、天玑 8400 上每步 20 s，VBench 总分与 14B 教师差 0.46–0.92。</p><p><strong>3 句话版</strong>：把任务收窄到三种运动模式明确的电影镜头效果，才让激进压缩成为可能。深度剪枝 + 两段 SFT + AdvDMD 四步蒸馏 + FFN 4bit 混合量化，逐级压到手机上。VBench 分数接近教师，但增益的绝大部分来自步数蒸馏，剪枝与量化主要贡献的是显存。</p><p><strong>1 句话版</strong>：端侧视频生成的可行性首先由任务定义决定，其次才由压缩技术决定。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>去掉 Dynamic Degree 与相机控制两个维度后的 VBench 子集，仍能代表&quot;电影镜头效果生成得好不好&quot;。</strong></p><p>作者的理由本身是合理的：运动幅度不等于效果质量，且基线未针对这些效果适配。但后果是致命的——<strong>被移除的恰好是唯一能检测&quot;运动坍塌&quot;和&quot;效果是否真的做出来了&quot;的两个维度</strong>。保留下来的七项里，Subject Consistency、Background Consistency、Motion Smoothness、I2V Subject、I2V Background 五项都会因为输出更静止、更接近输入图而<strong>上升</strong>。一个退化成&quot;几乎不动的缓慢推拉&quot;的模型，在这套子集上完全可能拿到比真正做出子弹时间的模型更高的分。</p><p>这不是抽象担忧。步数蒸馏到 4 步、对抗损失 + GRPO 联合优化，是文献中反复观察到运动幅度下降的组合；而论文自己的 Table 2 显示 GRPO 主要抬的是 Imaging Quality 与 I2V 一致性，正是上述方向。</p><p>论文为这条假设提供的证据是：定性帧序列图（Figure 4/5/10/11/12）与一次人评。人评确实覆盖了 camera control 维度，且论文称该项最强——这是最相关的证据。但<strong>人评只有 50 条子弹时间视频、10 名参与者，且结果只以柱状图呈现、无任何数值、无置信区间、无标注者一致性统计</strong>，另外两种效果（滑动变焦、慢动作）完全没有主观评测覆盖。在唯一能验证核心 claim 的证据链上，样本量与呈现方式都不足以支撑结论。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现整条流水线，一周内可验证最关键的一环：</p><ul><li><strong>数据</strong>：论文的三类效果各取 50 条 prompt/图像，或用公开的子弹时间 LoRA 自行生成参考集。</li><li><strong>实现</strong>：只做&quot;步数蒸馏这一级&quot;的对照。取任意 1.3B 级 I2V 模型 + 一个子弹时间 LoRA 作教师，实现两个学生：(i) 只做 DMD 的 4 步学生，(ii) DMD + 判别器对抗 + 把判别器分数当 GRPO reward 的 4 步学生（复现 AdvDMD 的关键设计）。</li><li><strong>测量</strong>：三组指标——(a) 论文保留的七项 VBench；(b) <strong>论文剔除的 Dynamic Degree 与 VBench 相机控制分</strong>；(c) 一个直接的效果保真代理：用 COLMAP 或任意单目位姿估计器从生成视频恢复相机轨迹，测轨迹与理想圆弧的角速度方差与半径漂移。</li><li><strong>判据</strong>：若 (a) 基本持平而 (b)(c) 在 4 步学生上显著劣于 20 步教师，就说明论文的评测子集系统性掩盖了压缩代价，主结论需要重新表述；若 (b)(c) 也保持，则论文的裁剪是安全的。(c) 尤其重要——它是唯一不依赖 VBench 也不依赖人评的客观效果指标，而全文缺的正是这个。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释一：GRPO 的收益来自&quot;再训一会儿&quot;而非奖励信号。</strong> Table 2 里 GRPO 带来 +0.52 / +0.47 的总分，但判别器分数<strong>同时</strong>充当对抗损失与 GRPO reward。这意味着 GRPO 并没有引入任何新的监督信息，它只是把同一个判别器信号换了一种优化方式再用一遍。缺的对照是&quot;关掉 GRPO 但把对抗训练多跑等量步数&quot;。若该对照也能拿到 +0.4 量级的提升，GRPO 这一组件的价值就被证伪。</p><p><strong>替代解释二：慢动作对比 FILM 的胜利部分来自训练数据的同源性。</strong> 慢动作的教师 LoRA 是用&quot;运动密集的底座输出经 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mord">×</span></span></span></span> 帧插值（FILM）&quot;构造的。也就是说，学生的慢动作先验有一部分<strong>继承自 FILM 本身的插值风格</strong>。随后在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20</span><span class="mord">×</span></span></span></span> 设定下与 FILM 对比并宣布获胜（PSNR 30.57→35.68），逻辑上是把 FILM 推到远超其设计工况的外推区间，而学生是在（部分由 FILM 定义的）分布内工作。公平的对照应当是：把 FILM 递归应用（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mord">×</span></span></span></span> 迭代若干次达到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20</span><span class="mord">×</span></span></span></span>）而非一次性 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20</span><span class="mord">×</span></span></span></span>，并同时报告一个不含 FILM 成分的慢动作真值集上的结果。</p><p><strong>替代解释三：VBench 差距小是因为指标饱和。</strong> Table 1 的 General 面板里，HunyuanVideo-1.5（8.3B/12 步）89.83、LTX2.3（22B/12 步）89.42、Open-Sora2.0（11B/50 步）88.54、Wan2.1-v1.1-Fun（1.5B/20 步）88.81。<strong>11B 的 Open-Sora2.0 比 1.5B 的 Fun 还低 0.27 分</strong>。当参数量跨越近一个数量级、总分只波动 1.3 分时，这套指标对模型能力的判别力已经接近饱和。因此&quot;CineMobile 与 14B 教师只差 0.46–0.92&quot;这句话的信息量，远小于字面看上去的那么大。</p><p><strong>可预测的失败场景</strong>：整条流水线的效果先验全部来自 effect-specific LoRA 与教师生成的合成视频，训练图像还经 Qwen3-VL 过滤掉了&quot;多人、极端曝光、过近特写、背景过于简单、运动潜力不足&quot;的样本。换到多人合影、强逆光或背景空旷的真实手机照片上，模型应当可预测地退化——这类输入恰恰是手机相册里最常见的一类。论文没有报告任何分布外输入的结果。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>局限驱动</strong>：当前流水线是一条<strong>离线固定</strong>的三级压缩链：剪多少层、蒸馏到几步、哪些层用几 bit，全部在训练时定死，推理时对所有输入一视同仁。但真实手机场景的约束是动态的——电量、温度、后台负载、用户是要预览还是要成片，都在变；而不同输入图的难度差异也极大（简单背景的半身像 vs 复杂街景）。用一个固定 4 步、固定位宽的模型去覆盖所有情况，必然在一端浪费、在另一端崩坏。同时，论文自己的数据显示三级压缩的收益极不均衡（步数蒸馏 12.28→2.45 s，剪枝 16.42→12.28 s，量化几乎不影响速度），说明这三个旋钮的边际收益曲线形状完全不同，静态配比几乎不可能最优。</p><p><strong>新 framing</strong>：把&quot;压缩&quot;从模型属性变成<strong>推理时的可调策略</strong>，用一个统一的预算变量同时控制步数、层数与位宽。相邻领域可借的工具是 <strong>anytime prediction / early-exit 网络</strong>与 <strong>once-for-all 超网</strong>：训练一个&quot;嵌套&quot;的学生，使得它的前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 层子网、前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> 步子轨迹、以及不同位宽配置都各自是一个可用模型，且质量随预算单调上升。这与本文的 PPCL 区间蒸馏天然兼容——区间代理 block 本来就是可插拔的（论文里的 &quot;Pluggable&quot;），只是从未被当作运行时开关使用。</p><p><strong>第一个实验</strong>：在子弹时间任务上训一个&quot;双出口&quot;版本——同一套权重支持 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">27</span><span class="mord text"><span class="mord"> </span><span class="mord cjk_fallback">层</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4</span><span class="mord text"><span class="mord"> </span><span class="mord cjk_fallback">步</span></span><span class="mclose">)</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">20</span><span class="mord text"><span class="mord"> </span><span class="mord cjk_fallback">层</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mord text"><span class="mord"> </span><span class="mord cjk_fallback">步</span></span><span class="mclose">)</span></span></span></span> 两档，训练时随机采样档位（类似 sandwich rule）。测量三件事：(a) 高档位相对论文单档模型的 VBench 总分损失是否小于 0.2；(b) 低档位在天玑 8400 上的每步延迟与总延迟；(c) 用 §10 提出的相机轨迹指标看低档位下效果保真的退化曲线。若 (a) 成立，说明<strong>多档共存几乎免费</strong>，端侧视频生成应当从&quot;训一个尽可能小的模型&quot;重新框定为&quot;训一条质量-延迟的连续曲线&quot;，这会直接改变端侧模型的交付形态（预览用低档、导出用高档，同一份 1 GB 权重）。</p>',59)])])}const d=a(e,[["render",l]]);export{h as __pageData,d as default};
